script:
// Excel 导出 - 单个对象导出示例
// 查询单个用户
var user = db.selectOne("select id, username, email, create_time from sys_user where id = 1")

// 定义表头
var headers = {
    "id": "ID",
    "username": "用户名",
    "email": "邮箱",
    "create_time": "创建时间"
}

// 导出单个对象为 Excel（单行）
var excelBytes = excel.writeObject(user, headers)

// 设置响应头下载
response.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")
response.setHeader("Content-Disposition", "attachment;filename=" + URLEncoder.encode("用户详情.xlsx", "UTF-8"))
response.write(excelBytes)
